create table if not exists subject_resource_grant (id bigint not null auto_increment comment 'grant primary key', subject_type varchar(32) not null comment 'subject type', subject_id bigint not null comment 'employee id', resource_id bigint not null comment 'resource id', effect varchar(16) not null comment 'ALLOW or DENY', created_at datetime(3) not null default current_timestamp(3), updated_at datetime(3) not null default current_timestamp(3) on update current_timestamp(3), primary key(id), unique key uk_subject_resource_grant(subject_type, subject_id, resource_id), key ix_subject_grant_subject(subject_type, subject_id)) engine=InnoDB default charset=utf8mb4 comment='direct subject resource grants';
